INSERT INTO `wp_options` VALUES (192,'_transient_trx_addons_list_addons','a:21:{s:9:\"ai-helper\";a:4:{s:5:\"title\";s:9:\"AI Helper\";s:11:\"description\";s:76:\"A companion to write a title, excerpt and post content with AI technologies.\";s:7:\"version\";s:3:\"1.0\";s:8:\"uploaded\";s:10:\"2024-03-20\";}s:13:\"audio-effects\";a:5:{s:5:\"title\";s:13:\"Audio effects\";s:11:\"description\";s:100:\"Adds sound effects to the site: background music, hover and click sounds for links and buttons, etc.\";s:7:\"version\";s:3:\"1.4\";s:8:\"uploaded\";s:10:\"2021-12-20\";s:7:\"updated\";s:10:\"2024-03-20\";}s:9:\"bg-canvas\";a:5:{s:5:\"title\";s:18:\"Dynamic Background\";s:11:\"description\";s:91:\"Allows you to set control points between which the page background will change dynamically.\";s:7:\"version\";s:3:\"1.3\";s:8:\"uploaded\";s:10:\"2021-12-20\";s:7:\"updated\";s:10:\"2024-03-20\";}s:9:\"bg-colors\";a:5:{s:5:\"title\";s:17:\"Background colors\";s:11:\"description\";s:93:\"Reference colors for sections by which the background of the page will change when scrolling.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2021-12-20\";s:7:\"updated\";s:10:\"2024-03-20\";}s:9:\"bg-slides\";a:5:{s:5:\"title\";s:20:\"Background slideshow\";s:11:\"description\";s:93:\"Add images as background to Elementor\'s sections and change its with pan and kenburn effects.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2021-12-20\";s:7:\"updated\";s:10:\"2024-03-20\";}s:6:\"charts\";a:5:{s:5:\"title\";s:6:\"Charts\";s:11:\"description\";s:67:\"Adds a shortcode for creating different types of graphs and charts.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2022-01-04\";s:7:\"updated\";s:10:\"2024-03-20\";}s:11:\"cpt-to-cart\";a:5:{s:5:\"title\";s:11:\"CPT to Cart\";s:11:\"description\";s:61:\"Allows custom post types to be added to the WooCommerce cart.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2022-06-08\";s:7:\"updated\";s:10:\"2024-03-20\";}s:15:\"expand-collapse\";a:5:{s:5:\"title\";s:17:\"Expand / Collapse\";s:11:\"description\";s:45:\"Allows you to show more content in less area.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2021-12-03\";s:7:\"updated\";s:10:\"2024-03-20\";}s:13:\"image-effects\";a:5:{s:5:\"title\";s:13:\"Image effects\";s:11:\"description\";s:59:\"Adds modern image hover effects based on WebGL distortions.\";s:7:\"version\";s:3:\"1.7\";s:8:\"uploaded\";s:10:\"2021-12-03\";s:7:\"updated\";s:10:\"2024-03-20\";}s:10:\"image-mask\";a:5:{s:5:\"title\";s:15:\"Image as a mask\";s:11:\"description\";s:63:\"Show parts of elements through the opaque areas of the picture.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2021-12-03\";s:7:\"updated\";s:10:\"2024-03-20\";}s:12:\"image-scroll\";a:5:{s:5:\"title\";s:12:\"Image scroll\";s:11:\"description\";s:64:\"Scroll large image inside the fixed viewport on the mouse hover.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2021-12-03\";s:7:\"updated\";s:10:\"2024-03-20\";}s:12:\"mouse-helper\";a:5:{s:5:\"title\";s:12:\"Mouse helper\";s:11:\"description\";s:77:\"Displays dynamic suggestions when the mouse hovers over various page objects.\";s:7:\"version\";s:3:\"1.9\";s:8:\"uploaded\";s:10:\"2021-12-03\";s:7:\"updated\";s:10:\"2024-03-20\";}s:12:\"qw-extension\";a:5:{s:5:\"title\";s:12:\"QW Extension\";s:11:\"description\";s:70:\"Provides additional theme functionality: new widgets types and styles.\";s:7:\"version\";s:5:\"1.6.2\";s:8:\"uploaded\";s:10:\"2023-04-07\";s:7:\"updated\";s:10:\"2025-09-18\";}s:15:\"secondary-image\";a:5:{s:5:\"title\";s:15:\"Secondary image\";s:11:\"description\";s:112:\"Allows you to specify an additional image, which is displayed when the mouse is hovered over the featured image.\";s:7:\"version\";s:3:\"1.2\";s:8:\"uploaded\";s:10:\"2021-12-03\";s:7:\"updated\";s:10:\"2024-03-20\";}s:5:\"smoke\";a:5:{s:5:\"title\";s:11:\"Smoke / Fog\";s:11:\"description\";s:69:\"Adds a shortcode that creates smoke (fog) following the mouse cursor.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2022-02-01\";s:7:\"updated\";s:10:\"2024-03-20\";}s:3:\"spa\";a:5:{s:5:\"title\";s:8:\"SPA mode\";s:11:\"description\";s:65:\"Single Page Application imitation - preload pages on links hover.\";s:7:\"version\";s:3:\"1.1\";s:8:\"uploaded\";s:10:\"2022-06-08\";s:7:\"updated\";s:10:\"2024-03-20\";}s:17:\"advanced_trx_team\";a:3:{s:5:\"title\";s:23:\"Advanced Post Type Team\";s:11:\"description\";s:30:\"New custom fields for CPT Team\";s:7:\"version\";s:3:\"1.0\";}s:10:\"bp-widgets\";a:4:{s:5:\"title\";s:18:\"BuddyPress widgets\";s:11:\"description\";s:31:\"Adds BuddyPress plugin widgets.\";s:7:\"version\";s:3:\"1.4\";s:7:\"updated\";s:10:\"2025-05-19\";}s:19:\"elementor-templates\";a:5:{s:5:\"title\";s:19:\"Elementor Templates\";s:11:\"description\";s:164:\"Adds a support for downloadable block and page templates to Elementor, as well as basic support for theme colors and fonts in Site Settings - Global Colors / Fonts.\";s:7:\"version\";s:3:\"1.0\";s:8:\"uploaded\";s:10:\"2025-04-28\";s:7:\"updated\";s:10:\"2025-04-28\";}s:17:\"elementor-widgets\";a:5:{s:5:\"title\";s:17:\"Elementor Widgets\";s:11:\"description\";s:127:\"An additional set of fully customisable widgets for Elementor to display posts, testimonials, icons, info-blocks, headers, etc.\";s:7:\"version\";s:3:\"1.0\";s:8:\"uploaded\";s:10:\"2025-04-28\";s:7:\"updated\";s:10:\"2025-04-28\";}s:17:\"bp-social-network\";a:4:{s:5:\"title\";s:25:\"BuddyPress Social Network\";s:7:\"version\";s:3:\"1.2\";s:8:\"uploaded\";s:10:\"2025-05-30\";s:7:\"updated\";s:10:\"2025-09-22\";}}','off');
