r( \'DOMContentLoaded\', initBreakpoints );\n		}\n\n		// Try to init the breakpoints right away.\n		initBreakpoints();\n		document.addEventListener( \'DOMContentLoaded\', initBreakpoints );\n	})();\n</script>\n','off');
