INSERT INTO `wp_posts` VALUES (20479,1,'2022-01-19 13:26:23','2022-01-19 13:26:23','<!-- wp:paragraph -->\n<p>I\'m extremely happy with the quality of Ingenioso agency designs. I have given them a brief, and they created magic.  </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p> Designers of the agency exceeded my expectations. The final product is unique, beautiful, and engaging. </p>\n<!-- /wp:paragraph -->','Anna Louise','','publish','closed','closed','','anna-louise','','','2022-01-19 13:26:23','2022-01-19 13:26:23','',0,'https://ingenioso.themerex.net/?post_type=cpt_testimonials&amp;p=20479',0,'cpt_testimonials','',0);
